// The floating-point protocols and their generic parts. The concrete types
// (Float, Double, Float80) are generated by tools/gen-floats.py. The
// conversions between arbitrary binary floating-point types go through
// Float80, which holds every Float and Double value exactly.

/// The type of an unannotated floating-point literal.
public typealias FloatLiteralType = Double

@frozen public enum FloatingPointSign: Sendable {
  case plus
  case minus

  // The enum has Int raw values (0 and 1); the RawRepresentable conformance
  // comes with that protocol.
  @inlinable public init?(rawValue: Int) {
    if rawValue == 0 { self = .plus } else if rawValue == 1 { self = .minus } else { return nil }
  }
  @inlinable public var rawValue: Int {
    switch self {
    case .plus: return 0
    case .minus: return 1
    }
  }
  @_transparent public static func == (a: FloatingPointSign, b: FloatingPointSign) -> Bool {
    return a.rawValue == b.rawValue
  }
  @inlinable public var hashValue: Int { return rawValue.hashValue }
  @inlinable public func hash(into hasher: inout Hasher) { hasher.combine(rawValue) }
  @inlinable public func _rawHashValue(seed: Int) -> Int { return rawValue._rawHashValue(seed: seed) }
  public typealias RawValue = Int
}
extension FloatingPointSign: Hashable {}

@frozen public enum FloatingPointClassification: Sendable {
  case signalingNaN
  case quietNaN
  case negativeInfinity
  case negativeNormal
  case negativeSubnormal
  case negativeZero
  case positiveZero
  case positiveSubnormal
  case positiveNormal
  case positiveInfinity

  internal var _index: Int {
    switch self {
    case .signalingNaN: return 0
    case .quietNaN: return 1
    case .negativeInfinity: return 2
    case .negativeNormal: return 3
    case .negativeSubnormal: return 4
    case .negativeZero: return 5
    case .positiveZero: return 6
    case .positiveSubnormal: return 7
    case .positiveNormal: return 8
    case .positiveInfinity: return 9
    }
  }
  public static func == (a: FloatingPointClassification, b: FloatingPointClassification) -> Bool {
    return a._index == b._index
  }
  public func hash(into hasher: inout Hasher) { hasher.combine(_index) }
  public var hashValue: Int { return _hashValue(for: self) }
}
extension FloatingPointClassification: Hashable {}

public enum FloatingPointRoundingRule: Sendable {
  case toNearestOrAwayFromZero
  case toNearestOrEven
  case up
  case down
  case towardZero
  case awayFromZero

  internal var _index: Int {
    switch self {
    case .toNearestOrAwayFromZero: return 0
    case .toNearestOrEven: return 1
    case .up: return 2
    case .down: return 3
    case .towardZero: return 4
    case .awayFromZero: return 5
    }
  }
  public static func == (a: FloatingPointRoundingRule, b: FloatingPointRoundingRule) -> Bool {
    return a._index == b._index
  }
  public func hash(into hasher: inout Hasher) { hasher.combine(_index) }
  public var hashValue: Int { return _hashValue(for: self) }
}
extension FloatingPointRoundingRule: Hashable {}

// ---- FloatingPoint ---------------------------------------------------------------

public protocol FloatingPoint: Hashable, SignedNumeric, Strideable where Self == Self.Magnitude {
  associatedtype Exponent: SignedInteger
  init(sign: FloatingPointSign, exponent: Exponent, significand: Self)
  init(signOf: Self, magnitudeOf: Self)
  init(_ value: Int)
  init<Source: BinaryInteger>(_ value: Source)
  init?<Source: BinaryInteger>(exactly value: Source)
  static var radix: Int { get }
  static var nan: Self { get }
  static var signalingNaN: Self { get }
  static var infinity: Self { get }
  static var greatestFiniteMagnitude: Self { get }
  static var pi: Self { get }
  var ulp: Self { get }
  static var ulpOfOne: Self { get }
  static var leastNormalMagnitude: Self { get }
  static var leastNonzeroMagnitude: Self { get }
  var sign: FloatingPointSign { get }
  var exponent: Exponent { get }
  var significand: Self { get }
  override static func + (lhs: Self, rhs: Self) -> Self
  override static func += (lhs: inout Self, rhs: Self)
  override static prefix func - (operand: Self) -> Self
  override mutating func negate()
  override static func - (lhs: Self, rhs: Self) -> Self
  override static func -= (lhs: inout Self, rhs: Self)
  override static func * (lhs: Self, rhs: Self) -> Self
  override static func *= (lhs: inout Self, rhs: Self)
  static func / (lhs: Self, rhs: Self) -> Self
  static func /= (lhs: inout Self, rhs: Self)
  func remainder(dividingBy other: Self) -> Self
  mutating func formRemainder(dividingBy other: Self)
  func truncatingRemainder(dividingBy other: Self) -> Self
  mutating func formTruncatingRemainder(dividingBy other: Self)
  func squareRoot() -> Self
  mutating func formSquareRoot()
  func addingProduct(_ lhs: Self, _ rhs: Self) -> Self
  mutating func addProduct(_ lhs: Self, _ rhs: Self)
  static func minimum(_ x: Self, _ y: Self) -> Self
  static func maximum(_ x: Self, _ y: Self) -> Self
  static func minimumMagnitude(_ x: Self, _ y: Self) -> Self
  static func maximumMagnitude(_ x: Self, _ y: Self) -> Self
  func rounded(_ rule: FloatingPointRoundingRule) -> Self
  mutating func round(_ rule: FloatingPointRoundingRule)
  var nextUp: Self { get }
  var nextDown: Self { get }
  func isEqual(to other: Self) -> Bool
  func isLess(than other: Self) -> Bool
  func isLessThanOrEqualTo(_ other: Self) -> Bool
  func isTotallyOrdered(belowOrEqualTo other: Self) -> Bool
  var isNormal: Bool { get }
  var isFinite: Bool { get }
  var isZero: Bool { get }
  var isSubnormal: Bool { get }
  var isInfinite: Bool { get }
  var isNaN: Bool { get }
  var isSignalingNaN: Bool { get }
  var floatingPointClass: FloatingPointClassification { get }
  var isCanonical: Bool { get }
}

// IEEE comparisons: every comparison involving NaN is false.
extension FloatingPoint {
  @_transparent public static func == (lhs: Self, rhs: Self) -> Bool { return lhs.isEqual(to: rhs) }
  @_transparent public static func < (lhs: Self, rhs: Self) -> Bool { return lhs.isLess(than: rhs) }
  @_transparent public static func <= (lhs: Self, rhs: Self) -> Bool { return lhs.isLessThanOrEqualTo(rhs) }
  @_transparent public static func > (lhs: Self, rhs: Self) -> Bool { return rhs.isLess(than: lhs) }
  @_transparent public static func >= (lhs: Self, rhs: Self) -> Bool { return rhs.isLessThanOrEqualTo(lhs) }
}

extension FloatingPoint {
  @inlinable public static var ulpOfOne: Self { return (1 as Self).ulp }
  @_transparent public func rounded(_ rule: FloatingPointRoundingRule) -> Self {
    var r = self
    r.round(rule)
    return r
  }
  @_transparent public func rounded() -> Self { return rounded(.toNearestOrAwayFromZero) }
  @_transparent public mutating func round() { round(.toNearestOrAwayFromZero) }
  @inlinable public var nextDown: Self { return -(-self).nextUp }
  @inlinable public func truncatingRemainder(dividingBy other: Self) -> Self {
    var r = self
    r.formTruncatingRemainder(dividingBy: other)
    return r
  }
  @inlinable public func remainder(dividingBy other: Self) -> Self {
    var r = self
    r.formRemainder(dividingBy: other)
    return r
  }
  @_transparent public func squareRoot() -> Self {
    var r = self
    r.formSquareRoot()
    return r
  }
  @_transparent public func addingProduct(_ lhs: Self, _ rhs: Self) -> Self {
    var r = self
    r.addProduct(lhs, rhs)
    return r
  }
  // A NaN operand loses to a number; two NaNs give the first.
  @inlinable public static func minimum(_ x: Self, _ y: Self) -> Self {
    if y.isNaN || x <= y { return x }
    return y
  }
  @inlinable public static func maximum(_ x: Self, _ y: Self) -> Self {
    if y.isNaN || x > y { return x }
    return y
  }
  @inlinable public static func minimumMagnitude(_ x: Self, _ y: Self) -> Self {
    if y.isNaN || x.magnitude <= y.magnitude { return x }
    return y
  }
  @inlinable public static func maximumMagnitude(_ x: Self, _ y: Self) -> Self {
    if y.isNaN || x.magnitude > y.magnitude { return x }
    return y
  }
  @inlinable public var floatingPointClass: FloatingPointClassification {
    let negative = sign == .minus
    if isNaN { return isSignalingNaN ? .signalingNaN : .quietNaN }
    if isInfinite { return negative ? .negativeInfinity : .positiveInfinity }
    if isZero { return negative ? .negativeZero : .positiveZero }
    if isSubnormal { return negative ? .negativeSubnormal : .positiveSubnormal }
    return negative ? .negativeNormal : .positiveNormal
  }
}

// Strides over floating-point values compute each element from the start
// rather than accumulating, so rounding errors do not build up.
extension Strideable where Self: FloatingPoint, Self == Self.Stride {
  @inlinable
  public static func _step(after current: (index: Int?, value: Self), from start: Self, by distance: Self.Stride)
    -> (index: Int?, value: Self) {
    let i = (current.index ?? 0) + 1
    return (i, start.addingProduct(Self(i), distance))
  }
}

// ---- BinaryFloatingPoint -----------------------------------------------------------

public protocol BinaryFloatingPoint: ExpressibleByFloatLiteral, FloatingPoint {
  associatedtype RawSignificand: UnsignedInteger
  associatedtype RawExponent: UnsignedInteger
  init(sign: FloatingPointSign, exponentBitPattern: RawExponent, significandBitPattern: RawSignificand)
  init(_ value: Float)
  init(_ value: Double)
  init(_ value: Float80)
  init<Source: BinaryFloatingPoint>(_ value: Source)
  init?<Source: BinaryFloatingPoint>(exactly value: Source)
  static var exponentBitCount: Int { get }
  static var significandBitCount: Int { get }
  var exponentBitPattern: RawExponent { get }
  var significandBitPattern: RawSignificand { get }
  var binade: Self { get }
  var significandWidth: Int { get }
}

extension BinaryFloatingPoint {
  @inlinable public static var radix: Int { return 2 }

  @inlinable public init(signOf: Self, magnitudeOf: Self) {
    self.init(sign: signOf.sign,
              exponentBitPattern: magnitudeOf.exponentBitPattern,
              significandBitPattern: magnitudeOf.significandBitPattern)
  }

  /// Conversion from any binary floating-point type, rounded to nearest
  /// even, and whether it was exact. The value goes through Float80, which
  /// holds any source with at most 64 significand bits and 15 exponent bits
  /// exactly, so there is a single rounding.
  public static func _convert<Source: BinaryFloatingPoint>(from source: Source) -> (value: Self, exact: Bool) {
    let wide = Float80(_exactly: source)
    let value = Self(wide)
    if wide.isNaN { return (value, false) }
    return (value, Float80(_exactly: value) == wide)
  }
  @inlinable public init<Source: BinaryFloatingPoint>(_ value: Source) {
    self = Self._convert(from: value).value
  }
  @inlinable public init?<Source: BinaryFloatingPoint>(exactly value: Source) {
    let (v, exact) = Self._convert(from: value)
    if !exact { return nil }
    self = v
  }

  // Total order: -NaN < -inf < ... < -0 <= +0 < ... < +inf < +NaN, with
  // NaNs ordered by payload.
  @inlinable public func isTotallyOrdered(belowOrEqualTo other: Self) -> Bool {
    if self < other { return true }
    if other < self { return false }
    if sign != other.sign { return sign == .minus }
    if exponentBitPattern != other.exponentBitPattern {
      return (exponentBitPattern < other.exponentBitPattern) == (sign == .plus)
    }
    if significandBitPattern == other.significandBitPattern { return true }
    return (significandBitPattern < other.significandBitPattern) == (sign == .plus)
  }
}

extension BinaryFloatingPoint where RawSignificand: FixedWidthInteger {
  /// Conversion from any binary integer, rounded to nearest even, and
  /// whether it was exact. Integers of up to 64 bits are exact in Float80,
  /// so they are rounded once; wider ones keep a sticky bit.
  public static func _convert<Source: BinaryInteger>(from source: Source) -> (value: Self, exact: Bool) {
    let negative = source < (0 as Source)
    var wide: Float80
    var exact = true
    if let i = Int64(exactly: source) {
      wide = Float80(i)
    } else if let u = UInt64(exactly: source) {
      wide = Float80(u)
    } else {
      let magnitude = source.magnitude
      let shift = magnitude._binaryLogarithm() - 63
      var top = UInt64(truncatingIfNeeded: magnitude >> shift)
      if (magnitude & ((1 as Source.Magnitude) << shift - 1)) != (0 as Source.Magnitude) {
        top |= 1
        exact = false
      }
      wide = Float80(sign: negative ? .minus : .plus, exponent: shift, significand: Float80(top))
    }
    let value = Self(wide)
    return (value, exact && Float80(_exactly: value) == wide)
  }
  @inlinable public init<Source: BinaryInteger>(_ value: Source) {
    self = Self._convert(from: value).value
  }
  @inlinable public init?<Source: BinaryInteger>(exactly value: Source) {
    let (v, exact) = Self._convert(from: value)
    if !exact { return nil }
    self = v
  }
}

extension Float80 {
  /// Any binary floating-point value as a Float80: exact when the source
  /// has at most 64 significand bits and an exponent range within Float80's.
  @usableFromInline
  internal init<Source: BinaryFloatingPoint>(_exactly v: Source) {
    let negative = v.sign == .minus
    if v.isNaN { self = negative ? -Float80.nan : Float80.nan; return }
    if v.isInfinite { self = negative ? -Float80.infinity : Float80.infinity; return }
    if v.isZero { self = negative ? -0.0 : 0.0; return }
    let sb = Source.significandBitCount
    let bias = (1 &<< (Source.exponentBitCount - 1)) - 1
    let pattern = Int(truncatingIfNeeded: v.exponentBitPattern)
    var m = UInt64(truncatingIfNeeded: v.significandBitPattern)
    var e: Int
    if pattern == 0 {
      e = 1 - bias - sb
    } else {
      if sb < 64 { m |= (1 as UInt64) &<< UInt64(truncatingIfNeeded: sb) }
      e = pattern - bias - sb
    }
    self.init(sign: negative ? .minus : .plus, exponent: e, significand: Float80(m))
  }
}

// ---- integers from floating-point values -------------------------------------------

extension FixedWidthInteger {
  /// The source rounded toward zero, or nil when that is not representable;
  /// and whether the source was already an integer.
  @inlinable
  public static func _convert<Source: BinaryFloatingPoint>(from source: Source) -> (value: Self?, exact: Bool) {
    let wide = Float80(_exactly: source)
    if !wide.isFinite { return (nil, false) }
    let t = wide.rounded(.towardZero)
    let exact = t == wide
    if t.isZero { return (0, exact) }
    let negative = t < 0
    let e = t.exponent
    let m = t._explicitSignificand
    if e < 64 {
      let magnitude = m &>> UInt64(truncatingIfNeeded: 63 - e)
      if negative {
        if magnitude > (1 as UInt64) &<< 63 { return (nil, exact) }
        return (Self(exactly: 0 &- Int64(truncatingIfNeeded: magnitude)), exact)
      }
      return (Self(exactly: magnitude), exact)
    }
    // Wider than 64 bits: only types that wide can hold it.
    let needed = e + 1 + (Self.isSigned ? 1 : 0)
    if needed > Self.bitWidth {
      if !(negative && Self.isSigned && e + 1 == Self.bitWidth && m == (1 as UInt64) &<< 63) { return (nil, exact) }
    }
    let magnitude = Self(truncatingIfNeeded: m) << (e - 63)
    return (negative ? (0 as Self) &- magnitude : magnitude, exact)
  }

  /// The value rounded toward zero; traps when it is NaN, infinite or out
  /// of range.
  @inlinable public init<T: BinaryFloatingPoint>(_ source: T) {
    guard let v = Self._convert(from: source).value else { Builtin.int_trap() }
    self = v
  }
  @inlinable public init?<T: BinaryFloatingPoint>(exactly source: T) {
    let (v, exact) = Self._convert(from: source)
    guard exact, let v = v else { return nil }
    self = v
  }
}
